<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Services\Identity;
use App\Services\FinanceAccess as F;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class FinanceTest extends TestCase {
 use RefreshDatabase;
 private function team():array{$o=User::factory()->create();$a=User::factory()->create();$m=User::factory()->create();$e=User::factory()->create();$w=Workspace::create(['name'=>'Example','type'=>'business','owner_id'=>$o->id]);$w->members()->attach([$o->id=>['role'=>'owner'],$a->id=>['role'=>'admin'],$m->id=>['role'=>'manager'],$e->id=>['role'=>'member']]);return [$w,$o,$a,$m,$e];}
 private function login(User $u,Workspace $w):static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>$w->id])->withoutVite();}
 private function at(string $date='2026-11-27 12:00:00'):void{$this->travelTo(Carbon::parse($date,'UTC'));}
 private function account(string $currency='USD',string $name='Cash'):int{$this->post('/finance/accounts',['name'=>$name,'kind'=>'cash','currency'=>$currency,'opening'=>'0.00'])->assertRedirect();return DB::table('finance_accounts')->latest('id')->value('id');}
 private function category(string $kind='income'):int{$this->post('/finance/categories',['name'=>ucfirst($kind),'kind'=>$kind])->assertRedirect();return DB::table('finance_categories')->latest('id')->value('id');}
 private function entry(int $a,int $c,array $extra=[]):array{return array_merge(['account_id'=>$a,'category_id'=>$c,'title'=>'Example payment','kind'=>'income','amount'=>'19.95','local_date'=>'2026-11-27'],$extra);}
 public function test_guest_manager_member_and_private_permissions():void{$this->get('/finance')->assertRedirect('/login');[$w,$o,$a,$m,$e]=$this->team();$this->login($m,$w)->get('/finance')->assertForbidden();$this->get('/finance/export')->assertForbidden();$this->login($e,$w)->get('/finance')->assertForbidden();$this->get('/dashboard')->assertOk()->assertDontSee('Finance overview');$this->login($a,$w)->get('/finance')->assertOk();$p=Identity::personal($o);$p->members()->attach($a->id,['role'=>'admin']);$this->assertFalse(F::canView($p,$a));}
 public function test_exact_money_and_currency_reports():void{$this->at();[$w,$o]=$this->team();$this->login($o,$w);$a=$this->account();$b=$this->account('BDT','Taka');$c=$this->category();$this->post('/finance/transactions',$this->entry($a,$c,['amount'=>'0.10']))->assertRedirect();$this->post('/finance/transactions',$this->entry($a,$c,['amount'=>'0.20']))->assertRedirect();$this->post('/finance/transactions',$this->entry($b,$c,['amount'=>'100.25','currency'=>'USD']))->assertRedirect();$this->post('/finance/transactions',$this->entry($a,$c,['amount'=>'0.001']))->assertSessionHasErrors('amount');$s=collect(F::stats($w,$o,'2026-11'))->keyBy('currency');$this->assertSame('0.30',$s['USD']['income']);$this->assertSame('100.25',$s['BDT']['income']);$this->get('/finance')->assertOk()->assertSee('100.25');$this->get('/dashboard')->assertOk()->assertSee('Finance overview');}
 public function test_reversal_immutable_and_signed_totals():void{$this->at();[$w,$o]=$this->team();$this->login($o,$w);$a=$this->account();$c=$this->category('expense');$this->post('/finance/transactions',$this->entry($a,$c,['kind'=>'expense']))->assertRedirect();$id=DB::table('finance_transactions')->value('id');$d=['reason'=>'Duplicate','local_date'=>'2026-11-27'];$this->post('/finance/transactions/'.$id.'/reverse',$d)->assertRedirect();$this->post('/finance/transactions/'.$id.'/reverse',$d)->assertSessionHasErrors('reason');$rev=DB::table('finance_transactions')->where('reversal_of',$id)->value('id');$this->post('/finance/transactions/'.$rev.'/reverse',$d)->assertSessionHasErrors('reason');$this->assertSame('0.00',F::stats($w,$o,'2026-11')[0]['expense']);$this->assertDatabaseCount('finance_transactions',2);}
 public function test_foreign_account_category_and_transaction_denied():void{$this->at();[$w,$o]=$this->team();$this->login($o,$w);$a=$this->account();$c=$this->category();$this->post('/finance/transactions',$this->entry($a,$c,['title'=>'Private income']))->assertRedirect();$id=DB::table('finance_transactions')->value('id');[$other,$owner]=$this->team();$this->login($owner,$other);$b=$this->account();$k=$this->category();$this->post('/finance/transactions',$this->entry($a,$k))->assertNotFound();$this->post('/finance/transactions',$this->entry($b,$c))->assertNotFound();$this->post('/finance/transactions/'.$id.'/reverse',['reason'=>'Foreign','local_date'=>'2026-11-27'])->assertNotFound();$this->get('/finance')->assertOk()->assertDontSee('Private income');}
 public function test_recurring_month_anchor_idempotency_and_revocation():void{$this->at('2026-01-31 12:00');[$w,$o,$a]=$this->team();$this->login($a,$w);$account=$this->account();$cat=$this->category();$d=$this->entry($account,$cat)+['frequency'=>'monthly','next_date'=>'2026-01-31'];$this->post('/finance/recurring',$d)->assertRedirect();$this->artisan('finance:tick')->assertExitCode(0);$this->artisan('finance:tick')->assertExitCode(0);$this->assertDatabaseCount('finance_transactions',1);$this->at('2026-02-28 12:00');$this->artisan('finance:tick')->assertExitCode(0);$this->assertDatabaseHas('finance_recurring',['next_date'=>'2026-03-31']);$this->login($o,$w)->patch('/workspaces/'.$w->id.'/members/'.$a->id,['role'=>'member'])->assertRedirect();$this->at('2026-03-31 12:00');$this->artisan('finance:tick')->assertExitCode(0);$this->assertDatabaseCount('finance_transactions',2);$this->assertDatabaseHas('finance_recurring',['active'=>0]);}
 public function test_budget_savings_and_rates():void{$this->at();[$w,$o]=$this->team();$this->login($o,$w);$a=$this->account();$c=$this->category('expense');$this->post('/finance/budgets',['category_id'=>$c,'month'=>'2026-11','currency'=>'USD','amount'=>'50'])->assertRedirect();$this->post('/finance/transactions',$this->entry($a,$c,['kind'=>'expense']))->assertRedirect();$this->post('/finance/savings',['name'=>'Emergency','currency'=>'USD','amount'=>'100'])->assertRedirect();$id=DB::table('finance_savings')->value('id');$this->patch('/finance/savings/'.$id,['amount'=>'25.10'])->assertRedirect();$this->post('/finance/rates',['local_date'=>'2026-11-27','bdt_per_usd'=>'120.123456'])->assertRedirect();$this->assertDatabaseHas('finance_savings',['saved_minor'=>2510]);$this->get('/finance')->assertOk()->assertSee('19.95 spent / 50.00')->assertSee('120.123456');}
 public function test_payroll_snapshot_and_single_payment():void{$this->at();[$w,$o,$admin,$m,$e]=$this->team();$this->login($o,$w);$a=$this->account();$b=$this->account('BDT','Other cash');$c=$this->category('expense');$this->post('/finance/salaries',['user_id'=>$e->id,'currency'=>'USD','amount'=>'100'])->assertRedirect();$s=DB::table('finance_salaries')->value('id');$d=['salary_id'=>$s,'month'=>'2026-11','bonus'=>'10.25','deduction'=>'5.10'];$this->post('/finance/payroll',$d)->assertRedirect();$this->post('/finance/payroll',$d)->assertSessionHasErrors('month');$p=DB::table('finance_payroll')->first();$this->assertSame(10515,(int)$p->net_minor);$pay=['account_id'=>$b,'category_id'=>$c,'local_date'=>'2026-11-27'];$this->post('/finance/payroll/'.$p->id.'/pay',$pay)->assertSessionHasErrors('account_id');$pay['account_id']=$a;$this->post('/finance/payroll/'.$p->id.'/pay',$pay)->assertRedirect();$this->post('/finance/payroll/'.$p->id.'/pay',$pay)->assertSessionHasErrors('account_id');$this->assertDatabaseCount('finance_transactions',1);$this->assertDatabaseHas('finance_transactions',['amount_minor'=>10515,'kind'=>'expense']);$this->login($e,$w)->get('/finance')->assertForbidden();}
 public function test_invoice_contact_snapshot_and_payment():void{$this->at();[$w,$o]=$this->team();$this->login($o,$w);$a=$this->account();$c=$this->category();$this->post('/crm/contacts',['name'=>'Client','lifecycle'=>'customer'])->assertRedirect();$contact=DB::table('crm_contacts')->value('id');$this->post('/finance/invoices',['contact_id'=>$contact,'title'=>'Invoice example','description'=>'<script>alert(1)</script>','currency'=>'USD','amount'=>'42.50','issue_date'=>'2026-11-27','due_date'=>'2026-12-10'])->assertRedirect();$id=DB::table('finance_invoices')->value('id');$this->get('/finance/invoices/'.$id)->assertOk()->assertSee('42.50')->assertDontSee('<script>alert(1)</script>',false);$pay=['account_id'=>$a,'category_id'=>$c,'local_date'=>'2026-11-27'];$this->post('/finance/invoices/'.$id.'/pay',$pay)->assertRedirect();$this->post('/finance/invoices/'.$id.'/pay',$pay)->assertSessionHasErrors('account_id');$tx=DB::table('finance_invoices')->value('transaction_id');$this->post('/finance/transactions/'.$tx.'/reverse',['reason'=>'Linked','local_date'=>'2026-11-27'])->assertSessionHasErrors('reason');$this->assertDatabaseCount('finance_transactions',1);}
 public function test_receipt_and_csv_isolation_and_formula_safety():void{Storage::fake('local');$this->at();[$w,$o]=$this->team();$this->login($o,$w);$a=$this->account();$c=$this->category();$this->post('/finance/transactions',$this->entry($a,$c,['title'=>'=1+1']))->assertRedirect();$t=DB::table('finance_transactions')->value('id');$this->post('/finance/transactions/'.$t.'/receipts',['file'=>UploadedFile::fake()->createWithContent('receipt.txt','example')])->assertRedirect();$r=DB::table('finance_receipts')->first();$this->get('/finance/receipts/'.$r->id)->assertOk()->assertDownload('receipt.txt');$response=$this->get('/finance/export?month=2026-11')->assertOk();$this->assertStringContainsString("'=1+1",$response->streamedContent());[$other,$owner]=$this->team();$this->login($owner,$other)->get('/finance/receipts/'.$r->id)->assertNotFound();$response=$this->get('/finance/export?month=2026-11')->assertOk();$this->assertStringNotContainsString('=1+1',$response->streamedContent());}
 public function test_personal_finance_and_business_only_payroll():void{$this->at();[$w,$o]=$this->team();$p=Identity::personal($o);$this->login($o,$p);$a=$this->account();$c=$this->category();$this->post('/finance/transactions',$this->entry($a,$c,['title'=>'Personal secret']))->assertRedirect();$this->get('/finance')->assertOk()->assertSee('Personal secret')->assertDontSee('Employee salary configuration');$this->post('/finance/salaries',['user_id'=>$o->id,'currency'=>'USD','amount'=>'100'])->assertForbidden();$this->login($o,$w)->get('/finance')->assertOk()->assertDontSee('Personal secret');}
}
